import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
class AdminDashboardScreen extends StatefulWidget{const AdminDashboardScreen({super.key});@override State<AdminDashboardScreen> createState()=>_AdminDashboardScreenState();}
class _AdminDashboardScreenState extends State<AdminDashboardScreen>{int tab=0;final names=['Dashboard','Orders','Products','Categories','Coupons','Reviews'];final collections=['orders','orders','products','categories','coupons','reviews'];Future<int> count(String c)async=>(await FirebaseFirestore.instance.collection(c).get()).size;Future<List<QueryDocumentSnapshot<Map<String,dynamic>>>> rows(String c)async=>(await FirebaseFirestore.instance.collection(c).limit(100).get()).docs;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text('FreshCart Admin — ${names[tab]}'),actions:[IconButton(onPressed:()async{await FirebaseAuth.instance.signOut();if(c.mounted)Navigator.pop(c);},icon:const Icon(Icons.logout))]),body:Row(children:[NavigationRail(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),labelType:NavigationRailLabelType.all,destinations:[for(final n in names)NavigationRailDestination(icon:const Icon(Icons.circle_outlined),selectedIcon:const Icon(Icons.circle),label:Text(n))]),Expanded(child:Padding(padding:const EdgeInsets.all(24),child:tab==0?_dashboard():_collection(collections[tab])))]));Widget _dashboard()=>FutureBuilder(future:Future.wait([count('orders'),count('users'),count('products')]),builder:(c,s){if(!s.hasData)return const CircularProgressIndicator();final x=s.data!;return GridView.count(crossAxisCount:3,childAspectRatio:2.2,crossAxisSpacing:16,mainAxisSpacing:16,children:[_stat('Orders',x[0]),_stat('Users',x[1]),_stat('Products',x[2])]);});Widget _stat(String t,int n)=>Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(t),const Spacer(),Text('$n',style:const TextStyle(fontSize:28,fontWeight:FontWeight.bold))])));Widget _collection(String name)=>FutureBuilder(future:rows(name),builder:(c,s){if(!s.hasData)return const CircularProgressIndicator();if(s.data!.isEmpty)return Text('No $name found');return ListView(children:s.data!.map((d)=>Card(child:ListTile(title:Text(d.id),subtitle:Text((d.data()['name']??d.data()['status']??d.data()['code']??d.data()['comment']??'').toString()),trailing:name=='orders'?DropdownButton<String>(value:d.data()['status']??'placed',items:const['placed','confirmed','packed','out_for_delivery','delivered','cancelled'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>FirebaseFirestore.instance.collection('orders').doc(d.id).update({'status':v})):null))).toList());});}
